import { app, BrowserWindow } from 'electron';
import { mkdirSync, writeFileSync } from 'node:fs';
const url=process.argv.find(arg=>arg.startsWith('http://'));app.setPath('userData',process.env.LINGXI_TEST_USER_DATA);const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function main(){await app.whenReady();const win=new BrowserWindow({show:false,width:1320,height:860,webPreferences:{sandbox:true,backgroundThrottling:false}});

try {await win.loadURL(url);const run=script=>win.webContents.executeJavaScript(script);const wait=async expr=>{for(let i=0;i<250;i++){if(await run(expr))return;await delay(20);}throw new Error(`Timeout ${expr}\n${await run('document.body.innerText')}`);};const click=sel=>run(`document.querySelector(${JSON.stringify(sel)}).click()`);const set=(sel,value)=>run(`(()=>{const e=document.querySelector(${JSON.stringify(sel)});Object.getOwnPropertyDescriptor(e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:e.tagName==='SELECT'?HTMLSelectElement.prototype:HTMLInputElement.prototype,'value').set.call(e,${JSON.stringify(value)});e.dispatchEvent(new Event(e.tagName==='SELECT'?'change':'input',{bubbles:true}));})()`);const page=value=>set('[aria-label="Review view"]',value);const result={};
await wait('document.querySelector(".git-file-row")');await click('[aria-label="Side by side diff"]');await wait('document.querySelector(".git-split-diff")');result.splitDiff=true;
await click('[title="src/workspace.ts"]');await wait('document.querySelector(".git-diff-title")?.textContent === "src/workspace.ts" && document.querySelector(".git-hunk")');
await run(`document.querySelector('.git-diff').style.minHeight='3000px';document.querySelector('.git-diff-scroll').scrollTop=150`);await delay(40);
await run(`window.originalHunk=document.querySelector('.git-hunk');window.gitFixture.holdDiff();window.gitFixture.bump()`);
await wait('window.gitFixture.diffPending()');result.backgroundDiffStaysMounted=await run('window.originalHunk.isConnected && !document.querySelector(".git-diff-scroll").textContent.includes("Loading diff")');
result.hunkDisabledDuringRefresh=await run('document.querySelector(".git-hunk button").disabled');
await run('window.gitFixture.releaseDiff()');await delay(60);result.backgroundRefreshKeepsScroll=await run('document.querySelector(".git-diff-scroll").scrollTop===150');result.unchangedDiffKeepsNode=await run('window.originalHunk===document.querySelector(".git-hunk")');
await run('window.gitFixture.editDiff()');await wait('document.querySelector(".git-diff")?.textContent.includes("再见")');result.sameStatsEditRefreshes=true;
await run('document.querySelector(".git-diff").style.minHeight="";window.gitFixture.holdDiff()');await click('[title="README.md"]');await wait('window.gitFixture.diffPending()');result.newFileClearsOldDiff=await run('!document.querySelector(".git-hunk") && document.querySelector(".git-diff-scroll").textContent.includes("Loading diff")');await run('window.gitFixture.releaseDiff()');await wait('document.querySelector(".git-hunk")');
await click('[title="src/workspace.ts"]');await wait('document.querySelector(".git-diff-title")?.textContent === "src/workspace.ts" && document.querySelector(".git-hunk")');
await set('[aria-label="Filter files"]','workspace');await wait('document.querySelectorAll(".git-file-row").length===1');result.fileFilter=true;await set('[aria-label="Filter files"]','');
await click('[aria-label="Discard src/workspace.ts"]');await wait('document.querySelector("dialog[open]")');const discardToken=await run('String(window.gitFixture.revision())');await run('window.gitFixture.bump()');await delay(50);await click('dialog .git-danger');await wait('window.gitFixture.calls.some(c=>c.request.kind==="discard")');result.discardFreezesSnapshot=await run(`window.gitFixture.calls.find(c=>c.request.kind==='discard').request.token===${JSON.stringify(discardToken)}`);
await click('[aria-label="Stage src/workspace.ts"]');await wait('window.gitFixture.calls.some(c=>c.request.kind==="stage")');result.stage=true;
await page('commit');await set('[aria-label="Commit message"]','Preserve this draft');await run('window.gitFixture.fail("commit")');await click('.git-primary');await wait('document.body.innerText.includes("Test operation failed")');result.failedDraftRetained=await run('document.querySelector("[aria-label=\\"Commit message\\"]").value==="Preserve this draft"');
await run('window.gitFixture.fail("");window.gitFixture.hold()');await click('.git-primary');await wait('document.body.innerText.includes("Running Git operation")');await run('document.querySelector("#composer").focus();window.gitFixture.session("b")');await wait('document.querySelector("[aria-label=\\"Switch branch\\"]").innerText.includes("feature/mobile")');await run('window.gitFixture.release()');await delay(60);result.oldMutationDoesNotLockSession=await run('!document.body.innerText.includes("Running Git operation") && document.activeElement.id==="composer"');
await run('window.gitFixture.session("a")');await wait('document.querySelector("[aria-label=\\"Commit message\\"]")');result.sessionDraftRestored=await run('document.querySelector("[aria-label=\\"Commit message\\"]").value==="Preserve this draft"');
await run('window.gitFixture.clean()');await delay(80);await click('[aria-label="Switch branch"]');await wait('document.querySelector("dialog[open]")');await set('[aria-label="Search branches"]','occupied');result.occupiedBranchDisabled=await run('document.querySelector(".git-branch-row").disabled');await set('[aria-label="Search branches"]','');await set('[aria-label="New branch name"]','feature/review');await click('dialog form button');await wait('!document.querySelector("dialog[open]")');result.branchCreated=await run('window.gitFixture.calls.some(c=>c.request.kind==="checkout"&&c.request.create&&c.request.branch==="feature/review")');
await page('history');await wait('document.querySelector(".git-history-row")');await click('.git-history-row');await wait('document.querySelector(".git-commit-meta")');result.history=true;
await page('stash');await wait('document.querySelector(".git-stash-row")');await click('.git-stash-row .git-actions button');await wait('window.gitFixture.calls.some(c=>c.request.kind==="stashApply")');result.stashApply=true;await run('Array.from(document.querySelectorAll(".git-stash-row button")).find(b=>b.textContent==="Delete").click()');await wait('document.querySelector("dialog[open]")');result.stashDeleteConfirmed=await run('!window.gitFixture.calls.some(c=>c.request.kind==="stashDrop")');await click('dialog .git-danger');await wait('window.gitFixture.calls.some(c=>c.request.kind==="stashDrop")');
await page('sync');await wait('document.querySelector("[aria-label=\\"Remote branch\\"]")');await run('Array.from(document.querySelectorAll(".git-actions button")).find(b=>b.textContent==="Fetch").click()');await wait('window.gitFixture.calls.some(c=>c.request.kind==="fetch")');result.fetch=true;
await run('window.gitFixture.conflict()');await page('changes');await wait('document.body.innerText.includes("conflict.txt")');await click('[title="conflict.txt"]');await wait('document.querySelector("[aria-label=\\"Conflict result\\"]")');await run('Array.from(document.querySelectorAll("dialog button")).find(b=>b.textContent==="Use incoming").click()');await run('Array.from(document.querySelectorAll("dialog button")).find(b=>b.textContent==="Save result").click()');await wait('!document.querySelector("dialog .git-primary").disabled');const savedToken=await run('String(window.gitFixture.revision())');await run('window.gitFixture.bump()');await delay(50);await click('dialog .git-primary');await wait('!document.querySelector("dialog[open]")');result.conflictUsesSavedSnapshot=await run(`window.gitFixture.calls.find(c=>c.request.kind==='conflictResolve').request.token===${JSON.stringify(savedToken)}`);result.conflictResolved=await run('window.gitFixture.calls.some(c=>c.request.kind==="conflictSave"&&c.request.side==="theirs")&&window.gitFixture.calls.some(c=>c.request.kind==="conflictResolve")');
await run('window.gitFixture.conflict()');await wait('document.querySelector("[title=\\"conflict.txt\\"]")');await click('[title="conflict.txt"]');await wait('document.querySelector("dialog[open]")');await run('window.gitFixture.session("b")');await wait('!document.querySelector("dialog[open]")');result.scopeSwitchClosesConflict=true;
await run('window.gitFixture.session("a")');await delay(100);await set('[aria-label="Comparison"]','branch');await set('[aria-label="Target branch"]','origin/main');await wait('document.querySelector(".git-hunk")');const dir='/tmp/lingxi-git-ui';mkdirSync(dir,{recursive:true});await delay(100);writeFileSync(`${dir}/light.png`,(await win.webContents.capturePage()).toPNG());await run('window.gitFixture.theme(true)');await delay(100);writeFileSync(`${dir}/dark.png`,(await win.webContents.capturePage()).toPNG());result.themes=await run('getComputedStyle(document.querySelector(".git-review")).backgroundColor!=="rgb(255, 255, 255)"');
await run('window.gitFixture.theme(false)');await click('#overview-fixture [data-git-branch-trigger]');await wait('document.querySelector("dialog[open]")');result.environmentDetails=await run('![...document.querySelectorAll("#overview-fixture .git-environment-content > button")].some(button => button.textContent.trim() === "Local") && document.querySelector("#overview-fixture .git-environment-content").textContent.includes("Commit or push") && document.querySelector("dialog").innerText.includes("1 file has changes")');await delay(80);writeFileSync(`${dir}/environment-light.png`,(await win.webContents.capturePage()).toPNG());await run('window.gitFixture.theme(true)');await delay(80);writeFileSync(`${dir}/environment-dark.png`,(await win.webContents.capturePage()).toPNG());
console.log(JSON.stringify(result));win.destroy();app.exit(0);
}catch(e){console.error(e.stack);win.destroy();app.exit(1);}

}
void main();
